package ports

// Serializer defines JSON serialization/deserialization.
// Concrete implementations: zero-alloc runtime adapter (generated code)
// and encoding/json fallback.
type Serializer interface {
	MarshalJSON(v any) ([]byte, error)
	UnmarshalJSON(data []byte, v any) error
}

// Marshaler is implemented by types with code generated by
// nitro/codegen/json (see AppendJSON in _gen.go). When a type
// implements this interface, the framework uses the fast path
// without reflection (~3-8x faster than encoding/json).
type Marshaler interface {
	AppendJSON(buf []byte) []byte
}

// Unmarshaler is implemented by types with generated code (see
// ParseJSON in _gen.go). Used by Ctx.Bind for the fast path
// without reflection.
type Unmarshaler interface {
	ParseJSON(data []byte) bool
}
